// Generated by esquadro: do not edit. Importing a CSV file into a resource
// whose entity takes imports (@store(import)): the file, which field each
// column fills (remembered for the next file), a preview with what is
// wrong, and the import, all or none.
import { isApiError } from "@api"
import { useQueryClient } from "@tanstack/react-query"
import { AlertCircle, Download, FileUp, Upload } from "lucide-react"
import { useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Spinner } from "@/components/ui/spinner"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { api } from "../api.ts"
import { currency, locale } from "../config.ts"
import { resources } from "../resources.gen.ts"
import { currencyOf, importable, normalize, parseCsv, problemsCsv, readRows, suggest } from "./csv.ts"
import type { Csv, Lookup, RowProblem, Target } from "./csv.ts"
import { describe, fieldMessage } from "./errors.ts"
import { download } from "./export.ts"
import { t } from "./i18n.ts"
import type { FieldMeta, Rec, ResourceMeta } from "./meta.ts"
import { toast } from "./toast.tsx"

/** How many rows an import takes at most, as the API does. */
export const importMax = 5000

const IGNORE = "__ignore"
const PREVIEW = 8

function rememberedOf(meta: ResourceMeta): Record<string, string> {
  try {
    return JSON.parse(localStorage.getItem(`esquadro.import.${meta.name}`) ?? "{}") as Record<string, string>
  } catch {
    return {}
  }
}

function remember(meta: ResourceMeta, csv: Csv, targets: Target[]) {
  try {
    const all = rememberedOf(meta)
    csv.header.forEach((h, i) => (all[normalize(h)] = targets[i] ?? ""))
    localStorage.setItem(`esquadro.import.${meta.name}`, JSON.stringify(all))
  } catch {
    // Not remembered: the next file is matched by its names again.
  }
}

/** The records of a relation's resource by the text that shows them. */
async function lookupOf(field: FieldMeta): Promise<Lookup> {
  const out: Lookup = new Map()
  const target = (resources as unknown as Record<string, ResourceMeta | undefined>)[field.target ?? ""]
  if (!target || !field.display) return out
  const records = target.api(api as never)
  const add = (r: Rec) => {
    const key = normalize(String(r[field.display!] ?? ""))
    if (key) out.set(key, [...(out.get(key) ?? []), r.id])
  }
  if (target.pagination.includes("cursor")) {
    let after: string | undefined
    for (let n = 0; n < 100; n++) {
      const page = await records.list({ limit: 100, after })
      page.items.forEach(add)
      after = page.next
      if (!after) break
    }
  } else {
    for (let n = 1; n <= 100; n++) {
      const page = await records.list({ page: n, per_page: 100 })
      page.items.forEach(add)
      if (n >= (page.total_pages ?? 1)) break
    }
  }
  return out
}

type Step = "file" | "columns" | "preview"

export function ImportDialog({ meta, open, onOpenChange }: { meta: ResourceMeta; open: boolean; onOpenChange: (open: boolean) => void }) {
  const fields = importable(Object.values(meta.fields))
  const [step, setStep] = useState<Step>("file")
  const [csv, setCsv] = useState<Csv | null>(null)
  const [targets, setTargets] = useState<Target[]>([])
  const [read, setRead] = useState<{ records: Record<string, unknown>[]; problems: RowProblem[] } | null>(null)
  const [refused, setRefused] = useState<RowProblem[] | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const input = useRef<HTMLInputElement>(null)
  const queryClient = useQueryClient()

  const reset = () => {
    setStep("file")
    setCsv(null)
    setTargets([])
    setRead(null)
    setRefused(null)
    setError("")
    if (input.current) input.current.value = ""
  }

  const choose = async (file: File | undefined) => {
    if (!file) return
    setError("")
    const parsed = parseCsv(await file.text())
    if (parsed.rows.length === 0) return setError(t("importEmpty"))
    if (parsed.rows.length > importMax) return setError(t("importTooMany", { max: importMax }))
    setCsv(parsed)
    setTargets(suggest(parsed.header, fields, t("currency"), rememberedOf(meta)))
    setStep("columns")
  }

  const preview = async () => {
    if (!csv) return
    setBusy(true)
    setRefused(null)
    try {
      remember(meta, csv, targets)
      // Relations written by name are looked up among their records.
      const lookups: Record<string, Lookup> = {}
      for (const f of fields.filter((f) => f.kind === "relation" && targets.includes(f.name))) lookups[f.name] = await lookupOf(f)
      setRead(readRows(csv, targets, fields, { locale, currency, words: { yes: t("yes"), no: t("no") }, lookups }))
      setStep("preview")
    } catch (e) {
      toast(describe(e), "error")
    } finally {
      setBusy(false)
    }
  }

  const run = async () => {
    if (!read || !meta.api(api as never).import) return
    setBusy(true)
    try {
      const done = await meta.api(api as never).import!(read.records)
      toast(t("importDone", { created: done.created, updated: done.updated }))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
      onOpenChange(false)
      reset()
    } catch (e) {
      if (isApiError(e) && e.code === "import_refused") {
        setRefused(e.fields.map((f) => ({ row: f.row ?? 0, field: f.field, code: f.code })))
      } else {
        toast(describe(e), "error")
      }
    } finally {
      setBusy(false)
    }
  }

  const byName = new Map(fields.map((f) => [f.name, f]))
  const labelOf = (target: string) =>
    target.endsWith("#currency") ? `${byName.get(target.slice(0, -"#currency".length))?.label} (${t("currency")})` : (byName.get(target)?.label ?? target)
  const message = (p: RowProblem) => {
    const f = byName.get(p.field)
    return `${t("importRow", { row: p.row })} · ${f ? `${f.label}: ${fieldMessage(f, p.code)}` : fieldMessage({ name: "", label: "", kind: "text", required: false }, p.code)}`
  }
  const problems = refused ?? read?.problems ?? []
  const missing = fields.filter((f) => f.required && f.kind !== "bool" && f.default === undefined && !targets.includes(f.name))
  const mapped = targets.filter((x): x is string => x !== null && !x.endsWith("#currency"))
  const by = meta.import?.by ? byName.get(meta.import.by) : undefined

  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        onOpenChange(o)
        if (!o) reset()
      }}
    >
      <DialogContent className="sm:max-w-3xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileUp className="size-5" /> {t("importTitle", { name: meta.label.toLocaleLowerCase() })}
          </DialogTitle>
          <DialogDescription>
            {step === "file" && t("importFileHint")}
            {step === "columns" && t("importColumnsHint")}
            {step === "preview" && csv && t("importRows", { count: csv.rows.length })}
            {by && ` ${t("importBy", { field: by.label.toLocaleLowerCase() })}`}
          </DialogDescription>
        </DialogHeader>

        {step === "file" && (
          <div className="flex flex-col items-center gap-3 rounded-lg border border-dashed border-border p-10">
            <Upload className="size-8 text-muted-foreground" />
            <input ref={input} type="file" accept=".csv,text/csv" className="hidden" onChange={(e) => choose(e.target.files?.[0])} />
            <Button type="button" variant="outline" onClick={() => input.current?.click()}>
              {t("importChoose")}
            </Button>
            {error && <p className="text-sm text-destructive">{error}</p>}
          </div>
        )}

        {step === "columns" && csv && (
          <div className="flex max-h-[60vh] flex-col gap-3 overflow-y-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>{t("importColumn")}</TableHead>
                  <TableHead>{t("importField")}</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {csv.header.map((h, i) => (
                  <TableRow key={i}>
                    <TableCell>
                      <div className="font-medium">{h || "—"}</div>
                      <div className="max-w-64 truncate text-xs text-muted-foreground">{csv.rows[0]?.[i] ?? ""}</div>
                    </TableCell>
                    <TableCell>
                      <Select
                        value={targets[i] ?? IGNORE}
                        onValueChange={(v) =>
                          setTargets((all) => all.map((x, j) => (j === i ? (v === IGNORE ? null : v) : x === v ? null : x)))
                        }
                      >
                        <SelectTrigger className="w-64">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value={IGNORE}>{t("importIgnore")}</SelectItem>
                          {fields.flatMap((f) => (f.kind === "money" ? [f.name, currencyOf(f.name)] : [f.name])).map((name) => (
                            <SelectItem key={name} value={name}>
                              {labelOf(name)}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            {missing.length > 0 && (
              <p className="flex items-center gap-2 text-sm text-destructive">
                <AlertCircle className="size-4" /> {t("importMissing", { fields: missing.map((f) => f.label).join(", ") })}
              </p>
            )}
          </div>
        )}

        {step === "preview" && csv && read && (
          <div className="flex max-h-[60vh] flex-col gap-4 overflow-y-auto">
            <div className="overflow-x-auto rounded-lg border border-border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>#</TableHead>
                    {mapped.map((name) => (
                      <TableHead key={name}>{labelOf(name)}</TableHead>
                    ))}
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {csv.rows.slice(0, PREVIEW).map((cells, i) => (
                    <TableRow key={i}>
                      <TableCell className="text-muted-foreground tabular-nums">{i + 1}</TableCell>
                      {mapped.map((name) => {
                        const wrong = problems.some((p) => p.row === i + 1 && p.field === name)
                        return (
                          <TableCell key={name} className={wrong ? "bg-destructive/10 text-destructive" : undefined}>
                            {cells[targets.indexOf(name)] ?? ""}
                          </TableCell>
                        )
                      })}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
            {problems.length > 0 && (
              <div className="flex flex-col gap-2 rounded-lg border border-destructive/30 bg-destructive/5 p-4">
                <p className="flex items-center gap-2 text-sm font-semibold text-destructive">
                  <AlertCircle className="size-4" /> {refused ? t("importRefused") : t("importProblems", { count: problems.length })}
                </p>
                <ul className="flex flex-col gap-1 text-sm">
                  {problems.slice(0, 20).map((p, i) => (
                    <li key={i}>{message(p)}</li>
                  ))}
                  {problems.length > 20 && <li className="text-muted-foreground">…</li>}
                </ul>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="self-start"
                  onClick={() => download(`${meta.name}-${t("importErrorsFile")}.csv`, problemsCsv(csv, problems, message, t("importErrorColumn")))}
                >
                  <Download /> {t("importDownloadErrors")}
                </Button>
              </div>
            )}
          </div>
        )}

        <DialogFooter>
          {step !== "file" && (
            <Button type="button" variant="ghost" onClick={() => (step === "preview" ? setStep("columns") : reset())} disabled={busy}>
              {t("back")}
            </Button>
          )}
          {step === "columns" && (
            <Button type="button" onClick={preview} disabled={busy || missing.length > 0 || mapped.length === 0}>
              {busy && <Spinner />}
              {t("next")}
            </Button>
          )}
          {step === "preview" && csv && (
            <Button type="button" onClick={run} disabled={busy || problems.length > 0}>
              {busy && <Spinner />}
              {t("importRun", { count: csv.rows.length })}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
